Add logging to this NestJS auth service. It handles JWT issuance and user login — I need to be able to trace auth events in production.

```typescript
// auth.service.ts
import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { UsersService } from '../users/users.service';
import * as bcrypt from 'bcrypt';

@Injectable()
export class AuthService {
  constructor(
    private readonly usersService: UsersService,
    private readonly jwtService: JwtService,
  ) {}

  async validateUser(email: string, password: string) {
    const user = await this.usersService.findByEmail(email);
    if (!user) return null;
    const valid = await bcrypt.compare(password, user.passwordHash);
    if (!valid) return null;
    return user;
  }

  async login(email: string, password: string) {
    const user = await this.validateUser(email, password);
    if (!user) throw new UnauthorizedException('Invalid credentials');
    const payload = { sub: user.id, email: user.email, roles: user.roles };
    return { accessToken: this.jwtService.sign(payload) };
  }

  async logout(userId: string) {
    await this.usersService.clearRefreshToken(userId);
  }
}
```

This Express router has no logging at all. Add structured logging with pino. I already have pino-http set up as middleware so req.log is available.

```typescript
// routes/orders.ts
import { Router, Request, Response, NextFunction } from 'express';
import { OrdersService } from '../services/orders.service';
import { validateCreateOrder } from '../validators/orders.validator';

const router = Router();
const ordersService = new OrdersService();

router.get('/', async (req: Request, res: Response, next: NextFunction) => {
  const { userId } = req.user as { userId: string };
  const orders = await ordersService.findByUser(userId).catch(next);
  res.json(orders);
});

router.post('/', async (req: Request, res: Response, next: NextFunction) => {
  const { userId } = req.user as { userId: string };
  const { error, value } = validateCreateOrder(req.body);
  if (error) return res.status(400).json({ error: error.message });
  try {
    const order = await ordersService.create(userId, value);
    res.status(201).json(order);
  } catch (err) {
    next(err);
  }
});

router.delete('/:id', async (req: Request, res: Response, next: NextFunction) => {
  const { userId } = req.user as { userId: string };
  const { id } = req.params;
  try {
    await ordersService.delete(id, userId);
    res.status(204).send();
  } catch (err) {
    next(err);
  }
});
```

